// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List alert contacts
	// (GET /api/v2/alert-contacts)
	ListAlertContacts(c *gin.Context)
	// Create an alert contact
	// (POST /api/v2/alert-contacts)
	CreateAlertContact(c *gin.Context)
	// Delete an alert contact
	// (DELETE /api/v2/alert-contacts/{contactId})
	DeleteAlertContact(c *gin.Context, contactId ContactId)
	// Get an alert contact
	// (GET /api/v2/alert-contacts/{contactId})
	GetAlertContact(c *gin.Context, contactId ContactId)
	// Partially update an alert contact
	// (PATCH /api/v2/alert-contacts/{contactId})
	PatchAlertContact(c *gin.Context, contactId ContactId)
	// Create an access token
	// (POST /api/v2/auth/tokens)
	LoginUser(c *gin.Context)
	// List maintenance windows
	// (GET /api/v2/maintenance-windows)
	ListMaintenanceWindows(c *gin.Context)
	// Create a maintenance window
	// (POST /api/v2/maintenance-windows)
	CreateMaintenanceWindow(c *gin.Context)
	// Delete a maintenance window
	// (DELETE /api/v2/maintenance-windows/{windowId})
	DeleteMaintenanceWindow(c *gin.Context, windowId WindowId)
	// Get a maintenance window
	// (GET /api/v2/maintenance-windows/{windowId})
	GetMaintenanceWindow(c *gin.Context, windowId WindowId)
	// Partially update a maintenance window
	// (PATCH /api/v2/maintenance-windows/{windowId})
	PatchMaintenanceWindow(c *gin.Context, windowId WindowId)
	// Detach a monitor from a maintenance window
	// (DELETE /api/v2/maintenance-windows/{windowId}/monitors/{monitorId})
	DetachMonitorFromMaintenanceWindow(c *gin.Context, windowId WindowId, monitorId MonitorId)
	// Attach a monitor to a maintenance window
	// (PUT /api/v2/maintenance-windows/{windowId}/monitors/{monitorId})
	AttachMonitorToMaintenanceWindow(c *gin.Context, windowId WindowId, monitorId MonitorId)
	// List monitors
	// (GET /api/v2/monitors)
	ListMonitors(c *gin.Context)
	// Create a monitor
	// (POST /api/v2/monitors)
	CreateMonitor(c *gin.Context)
	// Delete a monitor
	// (DELETE /api/v2/monitors/{monitorId})
	DeleteMonitor(c *gin.Context, monitorId MonitorId)
	// Get a monitor
	// (GET /api/v2/monitors/{monitorId})
	GetMonitor(c *gin.Context, monitorId MonitorId)
	// Partially update a monitor
	// (PATCH /api/v2/monitors/{monitorId})
	PatchMonitor(c *gin.Context, monitorId MonitorId)
	// Detach an alert contact from a monitor
	// (DELETE /api/v2/monitors/{monitorId}/alert-contacts/{contactId})
	DetachAlertContact(c *gin.Context, monitorId MonitorId, contactId ContactId)
	// Attach an alert contact to a monitor
	// (PUT /api/v2/monitors/{monitorId}/alert-contacts/{contactId})
	AttachAlertContact(c *gin.Context, monitorId MonitorId, contactId ContactId)
	// List monitor checks
	// (GET /api/v2/monitors/{monitorId}/checks)
	ListMonitorChecks(c *gin.Context, monitorId MonitorId, params ListMonitorChecksParams)
	// Get monitor SLA
	// (GET /api/v2/monitors/{monitorId}/sla)
	GetMonitorSLA(c *gin.Context, monitorId MonitorId, params GetMonitorSLAParams)
	// List monitor status intervals
	// (GET /api/v2/monitors/{monitorId}/status-history)
	ListMonitorStatusHistory(c *gin.Context, monitorId MonitorId, params ListMonitorStatusHistoryParams)
	// Register a user
	// (POST /api/v2/users)
	RegisterUser(c *gin.Context)
}

// ServerInterfaceWrapper converts contexts to parameters.
