// ListAlertContacts operation middleware
func (siw *ServerInterfaceWrapper) ListAlertContacts(c *gin.Context) {

	c.Set(string(BearerAuthScopes), []string{})

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.ListAlertContacts(c)
}

